function storageChanged116(){if(Persistence117.blocked)throw Persistence117.error();const raw=localStorage.getItem(V10KEY),saved=raw?(()=>{try{return JSON.parse(raw)}catch{throw Persistence117.error()}})():null;if(saved&&!Persistence117.validateJourney(saved))throw Persistence117.error();return (saved?.storageRevision116||0)!==persistedRevision116;}
function restoreGraph116(target,source,seen=new WeakMap()){if(!source||typeof source!=='object')return source;if(seen.has(source))return seen.get(source);if(!target||typeof target!=='object'||Array.isArray(source)!==Array.isArray(target))target=Array.isArray(source)?[]:{};seen.set(source,target);if(Array.isArray(source)){const existing=target.slice(),used=new Set(),values=source.map((v,i)=>{const j=v&&typeof v==='object'&&v.id!==undefined?existing.findIndex((x,n)=>!used.has(n)&&x&&x.id===v.id):i;used.add(j);return restoreGraph116(existing[j],v,seen)});target.splice(0,target.length,...values);return target;}for(const key of Object.keys(target))if(!(key in source))delete target[key];for(const [key,value]of Object.entries(source))target[key]=restoreGraph116(target[key],value,seen);return target;}
function restoreShared117(saved){restoreGraph116(data,saved.data);for(const p of saved.profiles)Object.assign(person(p.id)||{},p);for(const [key,value]of Object.entries({contributions:saved.contributions,kpiRules:saved.rules,ruleHistory:saved.ruleHistory,requests:saved.requests,grants:saved.grants,archives:saved.archives}))v8[key]=restoreGraph116(v8[key],value);}
