 try{if(storageChanged116())throw conflictError116();const raw=localStorage.getItem(V10KEY),candidate=JSON.stringify({...ten,storageRevision116:persistedRevision116});if(raw===candidate){committedTen116=structuredClone(ten);committedData116=structuredClone(data);committedShared117=sharedSnapshot117();return;}if(!Persistence117.validateJourney(ten))throw Persistence117.error();const next=persistedRevision116+1;localStorage.setItem(V10KEY,JSON.stringify({...ten,storageRevision116:next}));try{if(raw&&Persistence117.validateJourney(JSON.parse(raw))&&JSON.parse(raw).legacyShared117)localStorage.setItem(Persistence117.backupKey,raw)}catch{};ten.storageRevision116=next;persistedRevision116=next;committedTen116=structuredClone(ten);committedData116=structuredClone(data);committedShared117=sharedSnapshot117();}
