function identityModal10(id){const m=RM10.getMember(ten,id);if(ten.role==='label'||!m.application)return;modal10(T('Pemeriksaan identitas','Identity review'),`<h3>${E(m.name)}</h3>${identityRead10(m.application.snapshot)}<p>${T('Kontrak disetujui dan pembayaran terkonfirmasi.','Contract accepted and payment confirmed.')}</p><div class="ten-actions">${b10(T('Setujui Aktivasi','Approve activation'),'identity_approve',id+'|'+m.application.version,'primary')}</div>${form10('identity_correct',`<input type="hidden" name="version" value="${m.application.version}">${select10('note',T('Minta perbaikan','Request corrections'),[[T('Foto identitas belum terbaca. Unggah foto yang lebih jelas.','The identity photo is unreadable. Upload a clearer image.'),T('Foto tidak terbaca','Unreadable photo')],[T('Alamat belum lengkap. Lengkapi alamat sesuai dokumen.','The address is incomplete. Complete it using the document.'),T('Alamat belum lengkap','Incomplete address')],[T('Nama penanggung jawab tidak sesuai dokumen. Periksa kembali.','The responsible person name does not match. Please check it.'),T('Nama tidak sesuai','Name mismatch')]],'')}`,id)}`);}
function banks10(){if(ten.role!=='super')return '';return `<div class="ten-grid">${card10(T('Pengajuan rekening','Bank applications'),ten.members.filter(m=>m.bank.pending?.status==='pending').map(m=>`<div class="ten-item"><div><strong>${E(m.name)}</strong><small>${E(m.bank.pending.bank)} · ${E(m.bank.pending.holder)}</small></div>${b10('↗','bank_review',m.id)}</div>`).join('')||`<div class="ten-empty">${T('Tidak ada rekening yang menunggu pemeriksaan.','No bank accounts awaiting review.')}</div>`,'full')}</div>`;}
function bankModal10(id){if(ten.role!=='super')return;const m=RM10.getMember(ten,id),p=m.bank.pending;if(!p)return;modal10(T('Pemeriksaan rekening','Bank review'),`<h3>${E(m.name)}</h3>${identityRead10(m.identity)}<p class="ten-bank">${E(p.bank)} · ${E(p.number)}<br><strong>${E(p.holder)}</strong></p>${m.bank.approved?`<p>${T('Rekening sebelumnya','Previous account')}: ${E(m.bank.approved.bank)} · ${E(m.bank.approved.number)}</p>`:''}<div class="ten-actions">${b10(T('Setujui rekening','Approve bank account'),'bank_approve',id+'|'+p.version,'primary')}</div>${form10('bank_correct',`<input type="hidden" name="version" value="${p.version}">${select10('note',T('Minta perbaikan','Request corrections'),[[T('Periksa kembali bank dan nomor rekening yang diajukan.','Check the submitted bank and account number.'),T('Bank atau nomor rekening salah','Incorrect bank or account number')],[T('Nama penerima tidak sesuai. Periksa nama pemilik rekening.','The recipient name does not match. Check the account holder.'),T('Nama penerima tidak sesuai','Recipient mismatch')],[T('Jelaskan hubungan penerima dengan penanggung jawab label.','Explain the recipient relationship to the label representative.'),T('Hubungan penerima perlu dijelaskan','Explain recipient relationship')]],'')}`,id)}`);}
function notification10(){const items=ten.notifications.filter(n=>n.member===ten.member).slice(0,5);const labels={activated:['Akun labelmu sudah aktif.','Your label account is active.'],revision:['Ada perbaikan yang perlu dikirim.','Corrections are required.'],reminder:['Batas revisi semakin dekat.','The revision deadline is approaching.'],timeout:['Pengajuan ditutup karena batas revisi terlewat.','Submission closed after the revision deadline.'],live:['Rilisan telah dikonfirmasi tayang.','Your release was confirmed live.'],identity_correction:['Identitas perlu diperbaiki.','Identity corrections are required.'],bank_correct:['Rekening perlu diperbaiki.','Bank details need corrections.'],bank_approve:['Rekening sudah disetujui.','Your bank account was approved.'],answer:['Petugas sudah menjawab pertanyaanmu.','Staff have answered your question.'],rejected:['Pengajuan tidak dapat dilanjutkan.','The submission could not proceed.'],date_error:['Tanggal rilis sedang kami perbaiki. Kamu tidak perlu mengirim ulang.','We are correcting the release date. No resubmission is needed.'],offer:['Ada pilihan jadwal dan layanan pengganti.','A revised date and service are available.'],not_found:['Rilisan belum ditemukan. Tim menindaklanjuti ke Believe.','The release was not found. Our team is following up with Believe.']};return items.map(n=>`<div class="ten-item"><div>${E(T(...(labels[n.key]||[T('Pengajuan tercatat','Submission recorded'),T('Pengajuan tercatat','Submission recorded')])))}<small>${date10(n.at,true)}</small></div></div>`).join('')||`<div class="ten-empty">${T('Belum ada pembaruan.','No updates yet.')}</div>`;}
function history10(){const rows=ten.events.filter(e=>!isLabel10()||e.target===ten.member||ten.releases.some(r=>r.id===e.target&&r.member===ten.member));const names={profile_edit:['Perubahan identitas disimpan atau diajukan','Identity changes saved or submitted'],profile_photo:['Foto profil diperbarui','Profile photo updated'],profile_approve:['Perubahan identitas disetujui','Identity changes approved'],profile_correct:['Perbaikan identitas diminta','Identity corrections requested'],draft:['Draft disimpan','Draft saved'],submit:['Pengajuan dikirim','Submission sent'],start:['Pemeriksaan dimulai','Review started'],revision:['Perbaikan diminta','Corrections requested'],resubmit:['Perbaikan dikirim','Corrections submitted'],approve:['Rilisan disetujui','Release approved'],deliver:['Dikirim ke Believe','Delivered to Believe'],codes:['Kode disimpan','Identifiers saved'],live:['Tayang dikonfirmasi','Live confirmed'],credit_return:['Alokasi kredit dikembalikan','Credit allocation returned'],identity_approve:['Aktivasi disetujui','Activation approved'],identity_correct:['Perbaikan identitas diminta','Identity correction requested'],bank_approve:['Rekening disetujui','Bank approved'],bank_correct:['Perbaikan rekening diminta','Bank correction requested'],bank_submit:['Rekening diajukan','Bank submitted'],apply:['Aktivasi diajukan','Activation submitted'],profile:['Identitas disimpan','Identity saved'],contract:['Kontrak disetujui','Contract accepted'],pay:['Pembayaran dikonfirmasi','Payment confirmed'],invoice:['Tagihan dibuat','Invoice created'],timeout:['Batas revisi terlewat','Revision deadline passed'],question:['Penjelasan diminta','Clarification requested'],answer:['Penjelasan diberikan','Clarification answered'],reject:['Pengajuan ditolak','Submission rejected'],cancel:['Pembatalan diminta','Cancellation requested'],cancel_confirm:['Pembatalan dikonfirmasi','Cancellation confirmed'],not_found:['Rilisan belum ditemukan','Release not found'],date_error:['Kesalahan tanggal dilaporkan','Date error reported'],followup:['Tindak lanjut dicatat','Follow-up recorded'],downgrade_offer:['Perubahan jadwal ditawarkan','Schedule change offered'],downgrade_accept:['Perubahan jadwal disetujui','Schedule change accepted'],reopen:['Draft baru dari pengajuan sebelumnya','New draft from previous submission']};return `<div class="ten-grid">${card10(T('Riwayat','History'),rows.slice(0,70).map(e=>`<div class="ten-item"><div><strong>${T(...(e.kind==='profile_edit'?(e.note==='submitted'?['Perubahan identitas diajukan','Identity changes submitted']:['Identitas diperbarui','Identity updated']):(names[e.kind]||[e.kind,e.kind])))}</strong><small>${E(e.target)} · ${date10(e.at,true)} · ${E(e.actor)}</small></div></div>`).join('')||`<div class="ten-empty">${T('Belum ada tindakan.','No actions yet.')}</div>`,'full')}</div>`;}
function plans10(){modal10(T('Pilihan paket','Plan selection'),form10('plan',select10('plan',T('Paket','Plan'),['Flex','Go','Pro','Business'].map(v=>[v,v]),member10().plan)+select10('period',T('Periode','Period'),[['month',T('Bulanan','Monthly')],['year',T('Tahunan','Annual')]],member10().period)+field10('credits',T('Kredit awal Flex','Initial Flex credits'),1,'number','min="1" max="500"')+`<p class="full">${T('Tagihan berlaku 24 jam. Masa langganan dimulai ketika akun siap beroperasi.','Invoices expire after 24 hours. Subscription time starts when the account can operate.')}</p>`));}
function purchase10(){modal10(T('Tambah kredit','Add credits'),`<p>${T('1 kredit = 1 lagu. Pilihan berikut hanya membantu mengisi jumlah pembelian.','1 credit = 1 track. These shortcuts only fill the purchase quantity.')}</p><div class="ten-actions">${[['single','Single'],['ep','EP'],['album','Album'],['manual',T('Jumlah sendiri','Custom')]].map(([id,l])=>b10(l,'creditpreset',id)).join('')}</div>${form10('purchase',field10('credits',T('Jumlah kredit','Credit quantity'),1,'number','min="1" max="500" required id="ten-quantity"')+`<div><small>${T('Total pembayaran','Payment total')}</small><div class="ten-value" id="ten-price">${money10(35000)}</div></div><p class="full">${T('Kredit tidak dikunci untuk jenis rilisan tertentu dan tidak kedaluwarsa.','Credits are not locked to a release type and never expire.')}</p>`)}`);}
