function releaseForm10(id){const r=id?RM10.getRelease(ten,id):null;if(!member10().active){toast(T('Selesaikan aktivasi terlebih dahulu.','Complete activation first.'));return;}tenDraftService=r?.service||'Standard';modal10(T('Siapkan rilisan','Prepare a release'),`<form data-ten-form="release_draft" data-id="${id||''}"><div class="ten-form">${field10('title',T('Judul rilisan','Release title'),r?.title||'','text','required')}${field10('artist',T('Artis','Artist'),r?.artist||'','text','required')}${field10('tracks',T('Jumlah lagu','Track count'),r?.tracks||1,'number','min="1" max="12" required id="ten-tracks"')}</div><div style="margin-top:22px">${service10(tenDraftService)}</div><div id="ten-service-detail">${serviceDetail10(tenDraftService,r?.tracks||1,r?.date)}</div>${info10('service','Biaya Standard 1, Express 2, MAX 3 kredit per lagu adalah angka simulasi yang belum final. Kalender libur belum terhubung. Jumat MAX sebelum 12.00 WIB dapat memilih Minggu.','Standard 1, Express 2, MAX 3 credits per track are provisional preview values. Holiday calendars are not connected. Friday MAX before noon WIB allows Sunday release.')}<div class="ten-actions"><button class="btn primary" type="submit">${T('Simpan draft','Save draft')}</button></div></form>`);}
function serviceDetail10(service,n,selected){const first=RM10.earliest(ten,service);return `<div class="ten-date"><small>${T('KREDIT YANG DIALOKASIKAN','CREDIT ALLOCATION')}</small><strong>${n*({Standard:1,Express:2,MAX:3}[service])} ${T('kredit','credits')}</strong><small>${T('Terpakai final setelah Tayang dikonfirmasi.','Final usage after Live confirmation.')}</small></div>${first?field10('date',T('Tanggal rilis','Release date'),selected&&selected>=first?selected:first,'date',`required min="${first}"`):`<div class="ten-inline-msg">${T('MAX untuk Minggu tidak tersedia setelah Jumat pukul 12.00 WIB. Pilih Express atau Standard.','MAX for Sunday is unavailable after Friday noon WIB. Choose Express or Standard.')}</div>`}`;}
function releaseActions106(r){const id=r.id,staff=!isLabel10(),closed=r.status==='closed';let actions='';
 if(isLabel10()){
  if(r.status==='draft')actions+=b10(T('Ubah draft','Edit draft'),'editrelease',id)+b10(T('Kirim rilisan','Submit release'),'submit',id,'primary');
  if(r.status==='revision')actions+=form10('resubmit',field10('title',T('Judul','Title'),r.title)+field10('artist',T('Artis','Artist'),r.artist)+`<label class="full">${T('Perbaikan atau tanggapan','Correction or response')}<textarea name="response" required></textarea></label>`,id)+(!r.pauseUsed?b10(T('Minta penjelasan','Ask for clarification'),'ask',id):'');
  if(!['closed','live','cancel_requested'].includes(r.status))actions+=b10(T('Batalkan pengajuan','Cancel submission'),'cancel',id,'danger');
  if(closed)actions+=b10(T('Ajukan ulang','Submit again'),'reopen',id);
  if(r.offer)actions+=`<div class="ten-date"><small>${T('PILIHAN PENGGANTI','REVISED OPTION')}</small><strong>${r.offer.service} · ${date10(r.offer.date)}</strong>${b10(T('Setujui perubahan & pengembalian selisih','Accept change & credit difference'),'downgrade_accept',id)}</div>`;
 }else{
  if(r.status==='submitted')actions+=b10(T('Mulai pemeriksaan','Start review'),'start',id,'primary');
  if(r.status==='review')actions+=b10(T('Setujui rilisan','Approve release'),'approve',id,'primary')+b10(T('Minta perbaikan','Request corrections'),'revisionform',id);
  if(r.status==='clarification')actions+=form10('answer',`<label class="full">${T('Jawaban untuk label','Response to label')}<textarea name="note" required></textarea></label>`,id);
  if(r.status==='approved')actions+=form10('deliver',check10('checked',T('Tanggal di Believe sudah sesuai dengan tanggal permintaan label.','The Believe date matches the label requested date.')),id);
  if(['delivered','followup'].includes(r.status)){
   actions+=`<hr class="ten-divider"><h3>${T('Kode rilisan','Release identifiers')}</h3>${form10('codes',field10('upc','UPC',r.upc||'','text','required')+field10('isrc',T('ISRC per lagu (pisahkan dengan koma)','ISRC per track (comma separated)'),r.isrc||'','text','required'),id)}<p class="ten-note">${T('Menyimpan kode tidak mengubah status menjadi Tayang.','Saving identifiers does not mark the release Live.')}</p><h3>${T('Periksa hasil distribusi','Check distribution results')}</h3>${b10(T('Sudah tayang','Already live'),'liveform',id,'primary')}${b10(T('Belum ditemukan','Not found'),'not_found',id)}${b10(T('Laporkan kesalahan tanggal','Report a date error'),'dateerror',id)}`;
   if(r.status==='followup')actions+=form10('followup',`<label class="full">${T('Tindak lanjut ke Believe','Follow-up with Believe')}<textarea name="note" required>${E(r.followup||'')}</textarea></label>`,id)+b10(T('Tawarkan jadwal pengganti','Offer a revised schedule'),'offerform',id);
  }
  if(r.status==='live')actions+=b10(T('Koreksi penandaan Tayang','Correct Live marking'),'dateerror',id);
  if(r.status==='cancel_requested')actions+=form10('cancel_confirm',check10('checked',T('Proses sudah dihentikan; pembatalan ke Believe sudah dipastikan jika pernah dikirim.','Processing has stopped; Believe cancellation is confirmed if previously delivered.')),id);
  if(!['draft','closed','live','cancel_requested'].includes(r.status))actions+=b10(T('Tolak pengajuan','Reject submission'),'rejectform',id,'danger');
 }
return actions;}
function releaseModal10(id){const r=RM10.getRelease(ten,id);if(!r||isLabel10()&&r.member!==ten.member)return;tenDetail=id;const staff=!isLabel10(),closed=r.status==='closed',alloc=r.allocation.reduce((a,x)=>a+x.amount,0);const actions=releaseActions106(r);
 modal10(E(r.title),`<div class="ten-row">${tag10(status10(r.status),r.status==='live'?'green':'')}<span>${r.service} · ${r.tracks} ${T('lagu','tracks')}</span></div><p>${E(r.artist)} · ${E(RM10.getMember(ten,r.member).name)}</p><div class="ten-date"><small>${T('TANGGAL RILIS YANG DIMINTA','REQUESTED RELEASE DATE')}</small><strong>${date10(r.originalDate||r.date)}</strong><small>${T('Cocokkan tanggal ini pada kalender Believe.','Match this date on the Believe calendar.')}</small>${r.originalDate&&r.originalDate!==r.date?`<p>${T('Jadwal pengganti disetujui','Agreed revised date')}: ${date10(r.date)}</p>`:''}</div><p>${r.creditState==='reserved'?T('Kredit dialokasikan','Credits reserved'):r.creditState==='consumed'?T('Kredit terpakai','Credits used'):r.creditState==='returned'?T('Alokasi sudah dilepas sesuai sumber kredit','Allocation released according to credit source'):T('Belum menggunakan kredit','No credit allocated')}: ${alloc}</p>${r.note?`<div class="ten-inline-msg">${E(r.note)}${r.deadline?`<br>${T('Kirim sebelum','Submit before')} ${date10(r.deadline,true)} WIB`:''}</div>`:''}${r.question?`<p>${T('Pertanyaan label','Label question')}: ${E(r.question)}</p>`:''}${r.answer?`<p>${T('Jawaban petugas','Staff response')}: ${E(r.answer)}</p>`:''}${r.response?`<p>${T('Perbaikan terakhir','Latest correction')}: ${E(r.response)}</p>`:''}${r.baseline&&staff?`<p>${T('Sebelumnya','Previously')}: ${E(r.baseline.title)} · ${E(r.baseline.artist)}</p>`:''}${r.incident==='date_error'?`<p>${T('Tanggal rilis sedang kami perbaiki. Label tidak perlu mengirim ulang.','We are correcting the release date. No label resubmission is needed.')}</p>`:''}${closed?`<p>${r.reason==='timeout'?T('Batas revisi terlewat. Data tetap tersimpan.','The revision deadline passed. Your data is retained.'):E(r.reason)}</p>`:''}<div class="ten-actions">${actions}</div>`);
 // Forms must remain full-width, even when mixed with action buttons.
 document.querySelectorAll('.ten-dialog .ten-actions>form').forEach(f=>f.style.width='100%');
}
let studio10;
function scene10(key){const pref={lang:ten.lang,theme:ten.theme,layout:ten.layout};ten=Object.assign(RM10.seed(),pref);let m=member10();
 if(key==='new'){ten.member='embun';m=member10();m.paid=false;m.lots=[];ten.page='credits';}
 if(key==='identity'){ten.member='embun';m=member10();RM10.act(ten,'profile',{identity:{person:'Laras Senja',address:'Jl. Nada 8, Jakarta',postal:'10110',document:true,country:'Indonesia'}});RM10.act(ten,'contract');RM10.act(ten,'apply');ten.role='admin';ten.page='members';}
 if(key==='bank'){m.bank.approved=null;m.bank.pending={bank:'BCA',number:'12345678',holder:'Nama berbeda',status:'pending',version:1};m.bank.version=1;ten.role='super';ten.page='banks';}
 if(key==='expired'){m.subscriptionEnd=new Date(ten.now-1).toISOString();m.lots=m.lots.filter(l=>l.type==='paid');ten.page='credits';}
 if(key==='fridaylate')ten.now=Date.parse('2026-09-25T13:00:00+07:00');
 if(['revision','date','replacement'].includes(key)){
  const id=RM10.act(ten,'draft',{title:'Cahaya Pulang',artist:'Nara',tracks:1,service:'Standard',date:RM10.earliest(ten,'Standard')});RM10.act(ten,'submit',{id});ten.role='admin';RM10.act(ten,'start',{id});
  if(key==='revision'){RM10.act(ten,'revision',{id,note:T('Perbaiki penulisan nama artis sesuai profil resmi.','Correct the artist name to match the official profile.')});ten.now+=22*RM10.H;ten.role='label';}
  if(key==='date'){RM10.act(ten,'approve',{id});RM10.act(ten,'deliver',{id,checked:true});RM10.act(ten,'date_error',{id,note:T('Tanggal yang dipilih di Believe lebih lambat dari permintaan label.','The Believe date was entered later than requested.')});}
  if(key==='replacement'){ten.now+=24*RM10.H;RM10.act(ten,'reject',{id,note:T('Pengajuan ditolak setelah pergantian hari.','Submission rejected after the day changed.')});ten.role='label';ten.page='credits';}
  if(key!=='replacement')ten.page='releases';
 }
 if(ten.role!=='label')state.user=ten.role==='super'?'jeck':'adovi';RM10.tick(ten);save10();closeModal();render();
}
function welcome10(){const m=member10();if(m.active&&!m.welcome){modal10('',`<div class="ten-welcome"><p>${T('Selamat datang di Rilis Musik','Welcome to Rilis Musik')}</p><h1>${E(m.name)}</h1><p>${T('Akun labelmu sudah aktif. Saatnya menghadirkan musikmu.','Your label account is active. It is time to share your music.')}</p>${b10(T('Buka Dashboard','Open Dashboard'),'welcome','','primary')}</div>`);}}
function document10(){modal10(T('Foto identitas','Identity image'),`<p>${T('Gunakan gambar contoh untuk mencoba orientasi dan pemotongan.','Use the sample image to try rotation and cropping.')}</p><div id="ten-document" class="ten-id" style="transition:transform .2s"><small>IDENTITY · SAMPLE ONLY</small><strong>LARAS SENJA</strong><small>0000000000000000<br>Jl. Nada 8 · Indonesia</small></div><div class="ten-actions">${b10(T('Putar 90°','Rotate 90°'),'rotate')}${b10(T('Sesuaikan area','Adjust crop'),'crop')}${b10(T('Gunakan dokumen contoh','Use sample document'),'docsave','','primary')}</div>${info10('doc','Kontrol ini mendemonstrasikan penyesuaian tampilan, bukan OCR atau pengesahan dokumen. Tidak menerima unggahan KTP asli dalam prototype.','These controls demonstrate image framing, not OCR or identity approval. This prototype does not accept real identity uploads.')}`);}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-ten]');if(!el)return;event.preventDefault();event.stopImmediatePropagation();const a=el.dataset.ten,id=el.dataset.id;
 try{
  if(a==='close'){closeModal();return;}
  if(a==='page'){ten.page=id;closeModal();render();return;}
  if(a==='language'){ten.lang=ten.lang==='id'?'en':'id';closeModal();render();return;}
  if(a==='theme'){ten.theme=ten.theme==='light'?'dark':'light';render();return;}
  if(a==='config')return;
  if(a==='studio'){studio10();return;}
  if(a==='role'){ten.role=id;ten.page='home';closeModal();render();if(isLabel10())welcome10();return;}
  if(a==='member'){ten.member=id;ten.role='label';ten.page='home';closeModal();render();welcome10();return;}
  if(a==='scene'){scene10(id);return;}
  if(a==='advance'){ten.now+=Number(id)*RM10.H;RM10.tick(ten);save10();closeModal();render();return;}
  if(a==='fail'){ten.failNext=true;save10();closeModal();toast(T('Prochain enregistrement simulé en échec.','Next save will fail.').replace('Prochain enregistrement simulé en échec.','Penyimpanan berikutnya akan gagal dalam simulasi.'));return;}
  if(a==='step'){flushProfile10();tenStep=Number(id);activationPopup102();return;}
  if(a==='plans'){plans10();return;}
  if(a==='purchase'){purchase10();return;}
  if(a==='creditpreset'){const input=document.querySelector('#ten-quantity');input.value=({single:1,ep:4,album:10,manual:1}[id]);input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();return;}
  if(a==='identity'){identityModal10(id);return;}
  if(a==='bank_review'){bankModal10(id);return;}
  if(a==='newrelease'||a==='editrelease'){releaseForm10(a==='editrelease'?id:null);return;}
  if(a==='release'){releaseModal10(id);return;}
  if(a==='service'){tenDraftService=id;document.querySelector('.ten-service').style.setProperty('--selected',['Standard','Express','MAX'].indexOf(id));document.querySelectorAll('.ten-service button').forEach(b=>b.classList.toggle('active',b.dataset.id===id));document.querySelector('#ten-service-detail').innerHTML=serviceDetail10(id,Number(document.querySelector('#ten-tracks').value)||1);return;}
  if(a==='welcome'){member10().welcome=true;ten.page='home';closeModal();render();return;}
  if(a==='document'){document10();return;}
  if(a==='rotate'){const d=document.querySelector('#ten-document');d.dataset.rotation=String((Number(d.dataset.rotation)||0)+90);d.style.transform=`rotate(${d.dataset.rotation}deg)`;return;}
  if(a==='crop'){const d=document.querySelector('#ten-document');d.style.clipPath=d.style.clipPath?'':'inset(7% round 12px)';return;}
  if(a==='docsave'){RM10.act(ten,'profile',{identity:{document:true}});save10();activationPopup102();return;}
  if(a==='later'){const f=document.querySelector('[data-ten-form=profile]');if(f){const v=Object.fromEntries(new FormData(f));RM10.act(ten,'profile',{name:v.name,identity:directoryIdentity(v)});}ten.page='home';closeModal();render();toast(T('Draft tersimpan.','Draft saved.'));return;}
  if(['revisionform','rejectform','dateerror','ask'].includes(a)){const titles={revisionform:T('Minta perbaikan','Request corrections'),rejectform:T('Tolak pengajuan','Reject submission'),dateerror:T('Koreksi kesalahan internal','Correct an internal error'),ask:T('Minta penjelasan','Ask for clarification')};modal10(titles[a],form10(({revisionform:'revision',rejectform:'reject',dateerror:'date_error',ask:'question'})[a],`<label class="full">${T('Keterangan','Details')}<textarea name="note" required></textarea></label>${a==='revisionform'?`<label class="ten-check full"><input type="checkbox" name="same">${T('Masalah sama dengan putaran sebelumnya','Same issue as the previous round')}</label>`:''}`,id));return;}
  if(a==='liveform'){modal10(T('Konfirmasi Tayang','Confirm Live'),form10('live',field10('link',T('Tautan platform yang diperiksa','Checked platform link'),'','url','required placeholder="https://…"')+check10('checked',T('Saya sudah memeriksa seluruh tautan distribusi yang tersedia.','I have checked all available distribution links.')),id));return;}
  if(a==='offerform'){modal10(T('Jadwal pengganti','Revised schedule'),form10('downgrade_offer',select10('service','Rilis Musik',[['Standard','Standard'],['Express','Express']],'Standard')+field10('date',T('Tanggal pengganti','Revised date'),RM10.earliest(ten,'Standard'),'date','required'),id));return;}
  if(a==='apply')flushProfile10();
  let payload={id};if(['identity_approve','bank_approve'].includes(a)){const parts=id.split('|');payload={member:parts[0],version:Number(parts[1]),identityReview:el.dataset.identityReview};}
  const result=RM10.act(ten,a,payload);save10();closeModal();render();if(a==='reopen')releaseForm10(result);else if(['start','approve','submit','not_found','downgrade_accept'].includes(a))releaseModal10(id);else toast(T('Perubahan tersimpan.','Changes saved.'));
 }catch(e){save10();toast(error10(e.message));}
},true);
document.addEventListener('submit',event=>{const f=event.target;if(!f.dataset.tenForm)return;event.preventDefault();event.stopImmediatePropagation();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),kind=f.dataset.tenForm,id=f.dataset.id;
 try{let result;
  if(kind==='profile')result=RM10.act(ten,'profile',{name:v.name,identity:directoryIdentity(v)});
  else if(kind==='contract'){result=RM10.act(ten,'contract');acceptContract102(member10());}
  else if(kind==='bank')result=RM10.act(ten,'bank_submit',v);
  else if(kind==='social'){member10().social=v.social;}
  else if(kind==='plan')result=RM10.act(ten,'invoice',{...v,credits:Number(v.credits)});
  else if(kind==='purchase')result=RM10.act(ten,'invoice',{plan:member10().plan,period:member10().period,kind:'credits',credits:Number(v.credits)});
  else if(kind==='release_draft')result=RM10.act(ten,'draft',{...v,id:id||undefined,tracks:Number(v.tracks),service:tenDraftService});
  else if(['identity_correct','bank_correct'].includes(kind))result=RM10.act(ten,kind,{...v,member:id,version:Number(v.version)});
  else result=RM10.act(ten,kind,{...v,id,checked:!!v.checked,same:!!v.same});
  if(ten.formDrafts)delete ten.formDrafts[draftKey10(f)];save10();closeModal();if(['plan','purchase'].includes(kind))ten.page='credits';render();
  if(['profile','contract'].includes(kind)&&!member10().active)activationPopup102();else if(kind==='release_draft')releaseModal10(result);else if(['codes','deliver','followup','resubmit','answer','downgrade_offer'].includes(kind))releaseModal10(id);else toast(T('Perubahan tersimpan.','Changes saved.'));
 }catch(e){toast(error10(e.message));save10();}
},true);
document.addEventListener('input',event=>{const f=event.target.closest('[data-ten-form]');if(f){ten.formDrafts=ten.formDrafts||{};ten.formDrafts[draftKey10(f)]=Object.fromEntries(new FormData(f));save10();}if(event.target.id==='ten-quantity'){document.querySelector('#ten-price').textContent=money10(Math.max(0,Number(event.target.value)||0)*35000);}if(event.target.id==='ten-tracks'){const date=document.querySelector('#ten-service-detail [name=date]')?.value;document.querySelector('#ten-service-detail').innerHTML=serviceDetail10(tenDraftService,Number(event.target.value)||1,date);}});

